## ---- 01: Bisection  (qmd line 61) ---------------------------------------------------

solve_oas_bisect <- function(price_target, cashflows, times, rate_paths,
                              tol = 1e-5, lo = -0.01, hi = 0.25,
                              max_iter = 50) {
  mc_value <- function(spread) {
    df <- get_discount_factors(rate_paths, spread = spread, times = times)
    mean(vapply(df$discount_factors,
                function(d) sum(cashflows * d), numeric(1)))
  }
  for (iter in seq_len(max_iter)) {
    if (hi - lo < tol) break
    mid <- 0.5 * (lo + hi)
    v <- mc_value(mid)
    if (v > price_target) lo <- mid else hi <- mid
  }
  0.5 * (lo + hi)
}


