## ---- 03: Lower-Level `binary_search_oas`  (qmd line 310) -----------------------------

# When you already have projected cashflows and want a direct solve:
# collapse the aggregated pool cashflows to a path-average vector per 100 par
cf_mat    <- sapply(pool_cf, function(a) rowSums(a[, 5, ]))  # periods x paths
cf_per100 <- rowMeans(cf_mat) * 100 / sum(deal_structure$bonds$balance)
times     <- seq_along(cf_per100) / 12

oas_direct <- binary_search_oas(
  cashflows    = cf_per100,
  times        = times,
  rate_paths   = rate_paths,
  market_price = 104.00,
  search_range = c(-200, 500),
  tolerance    = 0.01
)
oas_direct$oas   # in bps


